package practice;

import java.util.Arrays;

/**
 * Uploads waiting to be scanned, oldest first. The scanner thread takes them one at a time; an
 * operator can discard everything still waiting. Each upload carries its whole body, often
 * several megabytes, and the queue lives as long as the service.
 */
public class UploadQueue {

    /** One uploaded file. */
    public record Upload(String name, byte[] body) {}

    private Upload[] items = new Upload[8];
    private int head;      // index of the oldest upload
    private int count;     // uploads waiting

    /** Adds an upload behind the others. */
    public void put(Upload upload) {
        if (count == items.length) grow();
        items[(head + count) % items.length] = upload;
        count++;
    }

    /** How many uploads are waiting. */
    public int size() {
        return count;
    }

    private void grow() {
        Upload[] bigger = new Upload[items.length * 2];
        for (int i = 0; i < count; i++) bigger[i] = items[(head + i) % items.length];
        items = bigger;
        head = 0;
    }

    /** Removes and returns the oldest waiting upload, or null when none is waiting. */
    public Upload take() {
        if (count == 0) return null;
        Upload oldest = items[head];
        items[head] = null;
        head = (head + 1) % items.length;
        count--;
        return oldest;
    }

    /** Discards every waiting upload. */
    public void clear() {
        Arrays.fill(items, null);
        head = 0;
        count = 0;
    }
}

package practice;

import java.lang.ref.WeakReference;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            UploadQueue queue = new UploadQueue();
            for (int i = 1; i <= 10; i++) queue.put(new UploadQueue.Upload("scan-" + i + ".pdf", new byte[512 * 1024]));
            System.out.println("waiting: " + queue.size());
            System.out.println("scanner takes: " + queue.take().name());
            System.out.println("scanner takes: " + queue.take().name());
            System.out.println("waiting: " + queue.size());
            WeakReference<byte[]> scanned = scannedBody(queue);
            queue.clear();
            System.out.println("after clear, waiting: " + queue.size() + ", take gives: " + queue.take());
            for (int i = 0; i < 10 && scanned.get() != null; i++) System.gc();
            System.out.println("scanned body still in memory: " + (scanned.get() != null));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    private static WeakReference<byte[]> scannedBody(UploadQueue queue) {
        return new WeakReference<>(queue.take().body());
    }
}

